  const mesh=(geo,mat,parent=model)=>{const m=new THREE.Mesh(geo,mat);parent.add(m);return m;};
  const palm=mesh(new THREE.BoxGeometry(1.65,1.85,.55,3,3,2),carbon);palm.position.y=.4;const plate=mesh(new THREE.BoxGeometry(1.35,1.45,.07),titanium);plate.position.set(0,.45,.32);
  const inset=mesh(new THREE.BoxGeometry(1.05,1.15,.08),carbon);inset.position.set(0,.45,.37);
  const cuff=mesh(new THREE.CylinderGeometry(.64,.85,1.55,36,1,true),carbon);cuff.position.y=-1.4;const wrist=mesh(new THREE.TorusGeometry(.57,.13,14,36),titanium);wrist.rotation.x=Math.PI/2;wrist.position.y=-.68;const band=mesh(new THREE.TorusGeometry(.79,.028,12,36),teal);band.rotation.x=Math.PI/2;band.position.y=-2.15;
  for(const x of [-.59,.59]){const rail=mesh(new THREE.BoxGeometry(.045,1.4,.06),teal);rail.position.set(x,.45,.33);}
  const fingerRoots=[],knuckles=[];
  function finger(x,y,length,angle=0){const root=new THREE.Group();root.position.set(x,y,0);root.rotation.z=angle;model.add(root);fingerRoots.push(root);let current=root;for(let j=0;j<3;j++){const len=length*(j===0?.39:j===1?.34:.27);const joint=mesh(new THREE.SphereGeometry(.16,16,12),titanium,current);const accent=mesh(new THREE.TorusGeometry(.165,.024,8,20),teal,current);accent.rotation.y=Math.PI/2;const segment=mesh(new THREE.CapsuleGeometry(.125,len-.25,5,12),carbon,current);segment.position.y=len/2;const side=mesh(new THREE.BoxGeometry(.12,len*.6,.035),titanium,current);side.position.set(0,len/2,.13);const next=new THREE.Group();next.position.y=len;current.add(next);knuckles.push({group:current,index:j});current=next;}return root;}
  [-.61,-.2,.21,.61].forEach((x,i)=>finger(x,1.36,[1.65,2,1.84,1.48][i],(i-1.5)*-.035));const thumb=finger(-.9,.3,1.48,.83);thumb.rotation.y=-.3;
  for(const x of [-.55,.55])for(const y of [-.1,.95]){const screw=mesh(new THREE.CylinderGeometry(.045,.045,.04,12),titanium);screw.rotation.x=Math.PI/2;screw.position.set(x,y,.39);}
  const ring=mesh(new THREE.TorusGeometry(3.25,.007,6,100),new THREE.MeshBasicMaterial({color:0x41675c,transparent:true,opacity:.6}),scene);ring.rotation.x=.6;ring.rotation.y=.35;
  const resize=()=>{const w=container.clientWidth,h=container.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();render();};let visible=true,drag=false,last={x:0,y:0},rotationTarget=-.55,frame=0;
  function render(){renderer.render(scene,camera);}function tick(){if(!visible)return;frame=requestAnimationFrame(tick);if(!drag&&!reduced)rotationTarget+=.0015;model.rotation.y+=(rotationTarget-model.rotation.y)*.07;render();}
  renderer.domElement.addEventListener('pointerdown',e=>{drag=true;last={x:e.clientX,y:e.clientY};renderer.domElement.setPointerCapture(e.pointerId);});renderer.domElement.addEventListener('pointermove',e=>{if(!drag)return;rotationTarget+=(e.clientX-last.x)*.012;model.rotation.x=THREE.MathUtils.clamp(model.rotation.x+(e.clientY-last.y)*.007,-.9,.9);last={x:e.clientX,y:e.clientY};render();});const stop=()=>{drag=false;};renderer.domElement.addEventListener('pointerup',stop);renderer.domElement.addEventListener('pointercancel',stop);
  renderer.domElement.addEventListener('wheel',e=>{if(e.ctrlKey||e.metaKey){e.preventDefault();camera.position.z=THREE.MathUtils.clamp(camera.position.z+e.deltaY*.01,7,18);render();}},{passive:false});container.querySelector('.viewer-hint').textContent='Drag to rotate · Ctrl + scroll to zoom';
  document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{const view=button.dataset.view;if(view==='reset'){rotationTarget=-.55;model.rotation.set(.16,-.55,-.1);camera.position.z=12;document.querySelector('#grip').value=0;updateGrip(0);}else{materials.forEach(mat=>mat.wireframe=view==='wire');document.querySelectorAll('[data-view]:not([data-view=reset])').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button?'true':'false');});}render();}));
