  const sizeObserver=new ResizeObserver(resize);sizeObserver.observe(container);const visibility=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;cancelAnimationFrame(frame);if(visible&&!document.hidden)tick();});visibility.observe(container);document.addEventListener('visibilitychange',()=>{cancelAnimationFrame(frame);if(!document.hidden&&visible)tick();});
  renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();cancelAnimationFrame(frame);container.querySelector('.viewer-placeholder').hidden=false;document.querySelector('#viewer-status').textContent='The 3D view has stopped. Reload the page to try again.';});
